const NS='http://www.w3.org/2000/svg';const add=(p,t,a={},text)=>{const e=document.createElementNS(NS,t);for(const[k,v]of Object.entries(a))e.setAttribute(k,v);if(text!==undefined)e.textContent=text;p.append(e);return e;};
const axis=n=>n>=1e6?'$'+(n/1e6).toFixed(1)+'m':n>=1000?'$'+Math.round(n/1000)+'k':'$'+Math.round(n);
function ceiling(n){if(n<=0)return 100;const m=10**Math.floor(Math.log10(n));return [1,1.5,2,2.5,3,4,5,6,8,10].find(k=>k>=n/m)*m;}
export function drawMonthly(svg,buttons,{points,events,onOpen}){
 const w=Math.max(240,svg.parentElement.clientWidth),phone=w<600;const lanes=[],layout=events.map(e=>{const bw=phone?76:Math.min(195,Math.max(140,(e.label.length+7)*5.8)),cx=Math.max(bw/2+2,Math.min(w-bw/2-2,(phone?44:58)+(e.year-1992)/35*(w-(phone?64:82))));let lane=lanes.findIndex(end=>cx-bw/2>=end+6);if(lane<0){lane=lanes.length;lanes.push(-Infinity);}lanes[lane]=cx+bw/2;return {e,bw,cx,lane};});const step=phone?50:42;const top=Math.max(45,lanes.length*step+16),h=top+(phone?220:285)+36,bottom=h-36,left=phone?44:58,right=w-(phone?20:24),max=ceiling(Math.max(...points.flatMap(p=>[p.nominal,p.CPI,p.MEI]))*1.08);
 svg.parentElement.classList.toggle('compact-chart',phone);
 const X=y=>left+(y-1992)/35*(right-left),Y=v=>bottom-(bottom-top)*v/max;
 svg.replaceChildren();buttons.replaceChildren();svg.setAttribute('viewBox',`0 0 ${w} ${h}`);svg.dataset.range='1992-2027';add(svg,'title',{id:'chart-title'},'Monthly Medicare payments, 1992 to 2027');add(svg,'desc',{id:'chart-desc'},'Nominal payments in each year’s dollars, plus CPI-adjusted and MEI-adjusted payments in constant 2027 dollars. All three lines meet in 2027. Labeled event buttons open details. Exact yearly values are available in the comparison table and download.');
 for(let i=0;i<=4;i++){let v=max*i/4;add(svg,'line',{x1:left,x2:right,y1:Y(v),y2:Y(v),class:'grid-line'});add(svg,'text',{x:left-8,y:Y(v)+4,'text-anchor':'end',class:'axis-text'},axis(v));}
 for(const year of (phone?[1992,2000,2010,2020,2027]:[1992,1995,2000,2005,2010,2015,2020,2027]))add(svg,'text',{x:X(year),y:bottom+24,'text-anchor':year===1992?'start':year===2027||phone&&year===2020?'end':'middle',class:'axis-text'},year);
 for(const key of ['CPI','MEI','nominal']){add(svg,'path',{d:points.map((p,i)=>(i?'L':'M')+X(p.year)+','+Y(p[key])).join(' '),class:'monthly-line '+key});}
 for(const {e,bw,cx,lane} of layout){const b=document.createElement('button');b.type='button';b.className='event-button';b.dataset.year=e.year;b.setAttribute('aria-label',`${e.year}: ${e.label}. Open details`);b.setAttribute('aria-haspopup','dialog');const y=6+lane*step;b.style.cssText=`left:${cx-bw/2}px;top:${y}px;width:${bw}px`;const tag={1997:'RVU ↑',1999:'Expenses',2007:'RVU ↑',2021:'E/M RVU',2024:'G2211',2027:e.label.split(' ')[0]}[e.year];b.innerHTML=`<b>${e.year}</b><span>${phone?tag:e.label}</span><i aria-hidden="true">›</i>`;b.onclick=()=>onOpen(e.year,b);buttons.append(b);const point=points.find(p=>p.year===e.year);add(svg,'path',{d:`M ${X(e.year)} ${top-3} L ${X(e.year)} ${Y(point.nominal)}`,class:'event-guide'});add(svg,'circle',{cx:X(e.year),cy:Y(point.nominal),r:3.7,class:'event-point'});
 }

}
